1	package server
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"io"
7		"mime"
8		"net/http"
9		"net/url"
10		"sort"
11		"strings"
12		"sync"
13		"time"
14	)
15	
16	// maxProviderAddresses bounds the addresses one provider record may carry.
17	const maxProviderAddresses = 16
18	
19	// maxProviderBodySize bounds the wire size of a provider publication body.
20	// The protocol itself only bounds the address count; the cap just keeps an
21	// unbounded request from exhausting memory.
22	const maxProviderBodySize = 1 << 20
23	
24	// maxProviderTTL is the longest lifetime a provider record may announce.
25	const maxProviderTTL = 24 * time.Hour
26	
27	// providerRecord is one provider's advertised access locations for a CID.
28	type providerRecord struct {
29		addresses []string
30		expiresAt time.Time
31	}
32	
33	// providerDirectory is a process-local index of provider records keyed by
34	// CID and then provider ID. Publishing a record does not require the object
35	// to be stored locally; the directory takes no part in pinning, garbage
36	// collection or storage statistics, and records are not retained across
37	// restarts.
38	type providerDirectory struct {
39		mu      sync.RWMutex
40		records map[string]map[string]providerRecord
41	}
42	
43	func newProviderDirectory() *providerDirectory {
44		return &providerDirectory{records: make(map[string]map[string]providerRecord)}
45	}
46	
47	// put publishes or replaces the record for (cid, providerID) and reports
48	// whether a valid record existed at now. A first publication or a
49	// replacement of an expired record reports created == true; exactly one
50	// concurrent first publisher observes it for a given key.
51	func (d *providerDirectory) put(cid, providerID string, addresses []string, expiresAt, now time.Time) (created bool) {
52		d.mu.Lock()
53		defer d.mu.Unlock()
54		byProvider := d.records[cid]
55		if byProvider == nil {
56			byProvider = make(map[string]providerRecord)
57			d.records[cid] = byProvider
58		}
59		existing, found := byProvider[providerID]
60		created = !found || !existing.expiresAt.After(now)
61		byProvider[providerID] = providerRecord{
62			addresses: append([]string(nil), addresses...),
63			expiresAt: expiresAt,
64		}
65		return created
66	}
67	
68	// providerEntry is one live record in a point-in-time directory listing.
69	type providerEntry struct {
70		providerID string
71		addresses  []string
72		expiresAt  time.Time
73	}
74	
75	// list returns the records valid at now for cid, sorted by provider ID.
76	// The slice and its address arrays are copies, so callers keep a consistent
77	// snapshot even while other requests mutate the directory.
78	func (d *providerDirectory) list(cid string, now time.Time) []providerEntry {
79		d.mu.RLock()
80		defer d.mu.RUnlock()
81		entries := []providerEntry{}
82		for id, rec := range d.records[cid] {
83			if !rec.expiresAt.After(now) {
84				continue
85			}
86			entries = append(entries, providerEntry{
87				providerID: id,
88				addresses:  append([]string(nil), rec.addresses...),
89				expiresAt:  rec.expiresAt,
90			})
91		}
92		sort.Slice(entries, func(i, j int) bool { return entries[i].providerID < entries[j].providerID })
93		return entries
94	}
95	
96	// remove deletes the record for (cid, providerID) when one is in force at
97	// now, reporting whether such a record existed. Expired records are treated
98	// as absent.
99	func (d *providerDirectory) remove(cid, providerID string, now time.Time) bool {
100		d.mu.Lock()
101		defer d.mu.Unlock()
102		byProvider := d.records[cid]
103		rec, found := byProvider[providerID]
104		if !found || !rec.expiresAt.After(now) {
105			return false
106		}
