102	// getObject handles GET /v1/objects/{cid}.
103	func (s *store) getObject(w http.ResponseWriter, r *http.Request) {
104		if r.Method != http.MethodGet {
105			w.Header().Set("Allow", http.MethodGet)
106			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
107			return
108		}
109		obj := s.lookupObject(w, r)
110		if obj == nil {
111			return
112		}
113		w.Header().Set("Content-Type", "application/octet-stream")
114		w.Header().Set("Content-Length", strconv.Itoa(obj.size))
115		for _, chunk := range obj.chunks {
116			_, _ = w.Write(chunk)
117		}
118	}
119	
120	// getManifest handles GET /v1/objects/{cid}/manifest.
121	func (s *store) getManifest(w http.ResponseWriter, r *http.Request) {
122		if r.Method != http.MethodGet {
123			w.Header().Set("Allow", http.MethodGet)
124			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
125			return
